import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXR-001 — Operator feedback list (2026-11-11)","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/records/UXR-001-2026-11-11-operator-feedback.md","filePath":"uxs/records/UXR-001-2026-11-11-operator-feedback.md"}'),s={name:"uxs/records/UXR-001-2026-11-11-operator-feedback.md"};function d(n,t,i,l,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="uxr-001-—-operator-feedback-list-2026-11-11" tabindex="-1">UXR-001 — Operator feedback list (2026-11-11) <a class="header-anchor" href="#uxr-001-—-operator-feedback-list-2026-11-11" aria-label="Permalink to &quot;UXR-001 — Operator feedback list (2026-11-11)&quot;">​</a></h1><ul><li><strong>Date</strong>: 2026-11-11</li><li><strong>Who</strong>: the operator</li><li><strong>Full list</strong>: <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> lines 1–307, &quot;the operator&#39;s words (typos fixed)&quot;, one row per point with an id. This record summarises it by area and does not duplicate it.</li><li><strong>Related</strong>: the slice plan in the same file (lines 311–400), the decisions it produced (<a href="./../decisions/UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> to <a href="./../decisions/UXD-011-decisions-apply-project-wide">UXD-011</a>), and <a href="./../CHANGE-INVENTORY">CHANGE-INVENTORY</a>.</li></ul><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>A single list of everything the operator found wrong or missing on the site, from tiny text and turquoise links to Explore, Worlds, Catalog, Plan, Fly and Launch. The teal accent redesign planned for 0.9.9 is part of the list: &quot;operator: merge it in&quot; (plan line 5). The plan counts &quot;119&quot; points; counting the id rows in the file gives 120 (including GH1 and the dropped W5). Not reconciled here.</p><h2 id="the-points-by-area" tabindex="-1">The points, by area <a class="header-anchor" href="#the-points-by-area" aria-label="Permalink to &quot;The points, by area&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Ids</th><th>What the operator asked for</th></tr></thead><tbody><tr><td>Cross-cutting text</td><td>X1, X2</td><td>Text too tiny and italic for no reason; one set of text styles across the site; links not turquoise but the muted blue</td></tr><tr><td>Panels</td><td>P1 to P5</td><td>Overviews and labels too small and italic; no blue glow on the hero hover; the close X not drawn over scrolled content; &quot;Collector card&quot; becomes &quot;Share&quot;, higher</td></tr><tr><td>Science links</td><td>S1, S2</td><td>The same science links repeat across panels of one type; one to five per panel, varied</td></tr><tr><td>Controls</td><td>C1 to C3</td><td>Chips oversized and the only oval things; Earth&#39;s two chip groups; one unified filter pattern</td></tr><tr><td>Nav bar</td><td>N1</td><td>The upper-right of the nav is oversized; more compact, maybe second-level nav horizontal under the main nav</td></tr><tr><td>Random pages</td><td>RP1; G1 to G6; CR1 to CR3; CO1 to CO3; LI1 to LI3</td><td>One style across Gallery, Credits, Colophon, Library; italic and tiny leads; the long pages (collapse); totals on Colophon; Library additions; the deep-sky bottom line (G6)</td></tr><tr><td>Home</td><td>H1 to H8</td><td>Hero too big; Lab card missing in Learn; more engaging without scrolling; TV home; video and a full redesign questions; typography and styling</td></tr><tr><td>Explore, overall</td><td>E1 to E10</td><td>Welcome hint; scene too dark; chips clear selection; fixed-width ruler; select as well as open; link to the world pages; second-level nav versus the breadcrumb; reset view; layer explanations; graphical breadcrumbs</td></tr><tr><td>Explore, solar system</td><td>SS1 to SS4; EP1 to EP4</td><td>The Vega pill; the picker cut off; the planet-scales popup; &quot;who lives here&quot; focus; panel mission links; planet heroes true to the 3D render, pure planets only; actions too low</td></tr><tr><td>Orbit ruler</td><td>O1 to O7</td><td>One row per item; hover and click draw the regime in the scene; thumbnails; founding missions as links; mission list review; varied science links; collapsible</td></tr><tr><td>Explore index</td><td>I1 to I4</td><td>Richer rows, filters at the top, a colour per planet, every click focuses</td></tr><tr><td>Iconic missions</td><td>IM1 to IM7</td><td>A smaller panel top; milestone boxes sharp with date and number in the header; clicking opens the mission; New Horizons; the chip first</td></tr><tr><td>Stellar neighbourhood</td><td>SN1, SN2</td><td>Light-year circles unclear; star panel pushes the overview down (one hero, a Gallery tab, a link from stars to the constellation)</td></tr><tr><td>Milky Way and beyond</td><td>MW1 to MW6</td><td>Overlapping and jumping labels; panels unlike the others (and the Sagittarius A* image); unmarked clickable items; deep-sky heroes; the Sun ring too obvious</td></tr><tr><td>Catalog, programs</td><td>PG1 to PG9</td><td>The three filters unique to the page; empty sections hidden; related programs, surface sites and hardware as cards; programs with few missions; Cassini; hardware links</td></tr><tr><td>Catalog, missions</td><td>MI1 to MI5</td><td>Filters ugly and tiny; a better era filter; colour per agency in the filters; &quot;Fly this mission&quot; higher; add Kaguya and Chandrayaan-2</td></tr><tr><td>Catalog, fleet</td><td>FL1 to FL3</td><td>The same filter notes; the line-up looks hidden; Crew Dragon missions tab and no portraits</td></tr><tr><td>ISS</td><td>ISS1, ISS2</td><td>&quot;Watch live&quot; as a first-class chip; the assembly player&#39;s fixed height</td></tr><tr><td>Worlds</td><td>W1 to W7; WM1 to WM3; VE1</td><td>Welcome hint; the locate button and the &quot;As seen from you&quot; readout overlap the ruler; selected orbiters hidden; &quot;Stand here&quot; always an image; orbiters&#39; tab; traverse parity; index colours; Venus galleries (W5, the brackets, was dropped)</td></tr><tr><td>Plan</td><td>PL1 to PL3</td><td>A destination dropdown that is organised; the chosen launch carried to Fly; a launch sequence</td></tr><tr><td>Fly</td><td>FY1 to FY4</td><td>2D too dark; the first seconds of ascent move sideways; flight-plan markers on the play bar; tidier HUD rows</td></tr><tr><td>Launch</td><td>LA1</td><td>A launch camera on top moving around; the operator has example shots to share</td></tr><tr><td>GitHub</td><td>GH1</td><td>Refresh the README and all docs, with text and graphics, last</td></tr></tbody></table><h2 id="what-happened-to-it" tabindex="-1">What happened to it <a class="header-anchor" href="#what-happened-to-it" aria-label="Permalink to &quot;What happened to it&quot;">​</a></h2><ul><li><strong>Decisions the operator owns</strong> (D1 to D7) and <strong>questions</strong> (Q1 to Q10) were asked once, before the phase that needs them. Q1 and Q2 were answered on 2026-11-11 (<a href="./../decisions/UXD-001-ui-accent-blue-replaces-teal">UXD-001</a>, <a href="./../decisions/UXD-002-type-scale-and-the-11px-floor">UXD-002</a>); the rest are open (<a href="./../UXS-000-orrery-ux-architecture#open">UXS-000 §Open</a>).</li><li><strong>Clarifications from the operator&#39;s screenshots</strong> (2026-11-11, plan lines 417–458) covered MW3, SN2, G5 and G6, O6, W5 and W6. They produced <a href="./../decisions/UXD-006-mars-moon-square-brackets-dropped">UXD-006</a> (dropped) and the accepted <a href="./../decisions/UXD-007-panorama-opens-facing-the-photo">UXD-007</a> to <a href="./../decisions/UXD-010-ruler-regimes-each-get-their-own-science-card">UXD-010</a>; the operator accepted the fixes for W6, SN2, G5/G6 and O6 on 2026-11-11 (plan line 460), and MW3 is planned in slice B3 without a recorded operator go.</li><li><strong>Already checked, no work</strong>: CR3. All 1,203 Moon, Mars and Earth surface tiles map to a credit entry (539 hotspot provenance rows); on-screen attribution in the scenes was not audited (plan lines 319–321).</li><li><strong>Reduced to slices</strong>: the points reduce to the slice plan, one table per area (A to I), each with its &quot;done when&quot; (plan lines 311–400). The status of each slice is in the <a href="./../CHANGE-INVENTORY">change inventory</a>.</li><li><strong>Process the operator added the same day</strong>: no partial updates, a definition of done, and checks and balances for every slice (<a href="./../decisions/UXD-011-decisions-apply-project-wide">UXD-011</a>).</li><li><strong>To check at the end</strong>: science diagrams and Lab art keep their own colours &quot;for now&quot; (plan lines 462–465).</li></ul>',8)])])}const g=e(s,[["render",d]]);export{u as __pageData,g as default};
